  import express, { Express } from "express";
  import { ListStockLevelsUseCase } from "../application/list-stock-levels-use-case";
  import { seedCatalogue } from "./catalogue-seed";
  import { errorMiddleware } from "./error-middleware";
  import { InMemoryOrderRepository } from "./in-memory-order-repository";
  import { InMemoryProductRepository } from "./in-memory-product-repository";
  import { createOrderController } from "./order-module";
  import { StockController } from "./stock-controller";

  export function createApp(): Express {
    const orders = new InMemoryOrderRepository();
    const products = new InMemoryProductRepository(seedCatalogue());

    const app = express();
    app.use(express.json());
    app.use("/orders", createOrderController(orders, products).router());
    app.use("/stock", new StockController(new ListStockLevelsUseCase(products)).router());
    app.use(errorMiddleware);
    return app;
  }

